action.command:
cd /workspace/project && python3 - <<'PY'
import json,re
live=json.load(open("nm_live.json"))
liveset={r[0] for r in live}
seen=set(); allk=[]
for f in ["nm2_api.txt","nm_api_keys.txt","nm_ready.txt","nomask_live_keys.txt"]:
    try:
        for l in open(f):
            m=re.search(r"(nmk_live_[A-Za-z0-9]+)",l)
            if m and m.group(1) not in seen:
                seen.add(m.group(1)); allk.append((m.group(1), l.split("|")[0].strip()))
    except FileNotFoundError: pass
with open("nomask_live_keys.txt","w") as f:
    f.write("# nomask — AUDIT 2026-11-17 | base: https://api.nomask.ai/v1\n")
    f.write("# format: email | api_key | status   (ganti ke key berikutnya saat HTTP 402)\n")
    n=0
    for k,e in allk:
        if k in liveset:
            n+=1; f.write(f"{n:2d}. {e} | {k} | LIVE\n")
    f.write("# --- HABIS (402) ---\n")
    for k,e in allk:
        if k not in liveset: f.write(f" -- {e} | {k} | HABIS\n")
print("LIVE:",len(liveset),"| HABIS:",len(allk)-len(liveset),"| total:",len(allk))
PY
cat nomask_live_keys.txt

